INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_RGhhbA', 'Dhal', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/dhal/3890328785.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Svits krydderier, løg og hvidløg i en gryde i et par minutter.","2.","Brug lidt vand eller olie, så det ikke brænder på.","3.","Skyl linserne og put dem i gryden sammen med salt, sukker, tomatpure og vand.","4.","Lad retten koge i 25 minutter under låg.","5.","Smag til med salt og chili.","6.","Server retten sammen med ris og eksempelvis frisk koriander, mangochutney, ananasstykker, peanuts, tzatziki og brød.","Forret","Tilbehør","Gryderet","Næringsindhold:","Energiindhold for hele retten:","6566 kj / 1568 kcal","Næringsindhold pr. 100g","414 kj / 99 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t2.4 g","Protein:\t28.8 %\t7.0 g","Kulhydrat:\t65.2 %\t15.9 g","Fedt:\t6 %\t0.7 g","Alkohol:\t0 %\t0.0 g","7 stemmer","Bedøm opskriften","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":null,"amount":150,"unit":"g tørrede grønne linser","text":"150 g tørrede grønne linser"},{"raavare_id":"ing_extra_27","amount":250,"unit":"g tørrede røde linser","text":"250 g tørrede røde linser"},{"raavare_id":"ing_loeg","amount":1,"unit":"løg, hakket","text":"1 løg, hakket"},{"raavare_id":"ing_loeg","amount":4,"unit":"fed hvidløg, pressede","text":"4 fed hvidløg, pressede"},{"raavare_id":"ing_ris","amount":2,"unit":"tsk frisk koriander","text":"2 tsk frisk koriander"},{"raavare_id":"ing_spidskommen","amount":2,"unit":"tsk stødt spidskommen","text":"2 tsk stødt spidskommen"},{"raavare_id":"ing_chili","amount":2,"unit":"tsk stødt gurkemeje & evt. chilipulver","text":"2 tsk stødt gurkemeje & evt. chilipulver"},{"raavare_id":"ing_extra_43","amount":2,"unit":"tsk salt","text":"2 tsk salt"},{"raavare_id":"ing_extra_30","amount":1,"unit":"tsk sukker","text":"1 tsk sukker"},{"raavare_id":"ing_extra_1","amount":70,"unit":"g koncentreret tomatpuré","text":"70 g koncentreret tomatpuré"},{"raavare_id":null,"amount":1,"unit":"liter vand","text":"1 liter vand"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3VsZXJvZHNib2x', 'Gulerodsboller', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/gulerodsboller1/3318067509.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Der bliver ca. 16-18 boller.","2.","Lun kærnemælken og rør gæren ud.","3.","Rør groftrevne gulerødder og de øvrige ingredienser i dejen - hold lidt af melet tilbage.","4.","Sørg for at dejen ikke bliver for fast.","5.","Lad dejen hæve lunt, tildækket ca. 1 time.","6.","Sæt store spiseskefulde af dejen på plader med bagepapir og lad bollerne efterhæve 8-10 minutter.","7.","Bag bollerne gyldne og sprøde ved 200 grader i 20-25 minutter, og afkøl på en bagerist. Opskrift og styling: Udviklet af Vibeke Lehn.","Brød og kager","Brød og boller","Næringsindhold:","Energiindhold for hele retten:","20620 kj / 4925 kcal","Næringsindhold pr. 100g","769 kj / 184 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t4.3 g","Protein:\t13.8 %\t6.2 g","Kulhydrat:\t76.6 %\t34.6 g","Fedt:\t9.6 %\t2.0 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Snoet persillebrød med hvidhvede og øl","Brød og kager","60-90 min","Se opskrift","Fougasse med oliven og timian","Brød og kager","0-30 min","Se opskrift","Snoet hvidløgsbrød med urter","Brød og kager","0-30 min","Se opskrift","Rustikt grydebrød med havre","Tilbehør","30-60 min","Se opskrift","Ølandshvedebrød med kefir","Brød og kager","90-120 min","Se opskrift","Citronscones med hindbærcreme","Brød og kager","0-30 min","Se opskrift","Fastelavnsboller med vaniljecreme, fløde og syltetøj","Brød og kager","30-60 min","Se opskrift","Laktosefri flækkede fastelavnsboller","Brød og kager","0-30 min","Se opskrift","Langtidshævet foccacia med druer og rosmarin","Snacks","0-30 min","Se opskrift","Langtidshævet foccacia med Prima Donna og rødløg","Brød og kager","30-60 min","Se opskrift","Ostebrød med blåbær, rødløg og timian","Brød og kager","0-30 min","Se opskrift","Foccacia med rødbede og gedeost","Brød og kager","60-90 min","Se opskrift","Fastelavnsboller med sveske og creme – uden tilsat sukker","Brød og kager","30-60 min","Se opskrift","Nemt surdejsbrød med græskarkerner","Brød og kager","90-120 min","Se opskrift","Chokoladeboller med ølandshvede","Brød og kager","30-60 min","Se opskrift","Grydebrød med rødbede og ristede sesamfrø","Brød og kager","90-120 min","Se opskrift","Mormors fastelavnsboller med vaniljecreme","Brød og kager","90-120 min","Se opskrift","Butterdejsstænger med ost, sesam og oliventapenade","Madpakke","0-30 min","Se opskrift","Æblehorn","Brød og kager","30-60 min","Se opskrift","Stjernebrød med nøddecreme/Nutella","Brød og kager","90-120 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":null,"amount":50,"unit":"g gær","text":"50 g gær"},{"raavare_id":"ing_extra_26","amount":1,"unit":"liter kærnemælk","text":"1 liter kærnemælk"},{"raavare_id":"ing_extra_4","amount":4,"unit":"gulerødder","text":"4 gulerødder"},{"raavare_id":"ing_extra_43","amount":1,"unit":"spsk groft salt","text":"1 spsk groft salt"},{"raavare_id":null,"amount":1,"unit":"spsk honning","text":"1 spsk honning"},{"raavare_id":"ing_ris","amount":35,"unit":"g ristede pinjekerner","text":"35 g ristede pinjekerner"},{"raavare_id":null,"amount":2,"unit":"spsk revet appelsinskal (usprøjtet)","text":"2 spsk revet appelsinskal (usprøjtet)"},{"raavare_id":null,"amount":600,"unit":"g grahamsmel","text":"600 g grahamsmel"},{"raavar