INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_Q29xIGF1IHZpbg', 'Coq au vin', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/coq-au-vin-0/2836405550.jpeg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Varm smøret op i en sautepande til det bruser.","2.","Kom de 8 stykker kylling i og brun dem godt på alle sider, krydr med salt og peber.","3.","Tag derefter kyllingen op på et fad.","4.","Brun bacon, skalotteløg og champignons til det er gyldent i cirka 5 minutter.","5.","Kom vin på og lad det komme i kog.","6.","Tilsæt derefter hønsebouillon og lad det simre i 5 minutter.","7.","Kom de brunede kyllingestykker, hvidløg og timian i et ovnfast fad, hæld bacon og vin blandingen over og steges i ovn ved 160 grader i 35 minutter til kyllingen er mør.","8.","Smages til med salt, peber og frisk timian.","9.","Pynt med snittet bladselleri.","Fjerkræ","Svin","Hovedret","Næringsindhold:","Energiindhold for hele retten:","15105 kj / 3608 kcal","Næringsindhold pr. 100g","606 kj / 145 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.5 g","Protein:\t33.3 %\t11.9 g","Kulhydrat:\t10.6 %\t3.8 g","Fedt:\t49.7 %\t8.1 g","Alkohol:\t6.4 %\t1.3 g","2 stemmer","Bedøm opskriften","Relaterede opskrifter","Friske forårsruller med citrongræsgris","Hovedret","30-60 min","Se opskrift","Kalkunrulle fyldt med parmaskinke og rosmarin serveret med polenta","Hovedret","0-30 min","Se opskrift","Lasagne med gris, fennikel og ricotta","Hovedret","30-60 min","Se opskrift","Kyllingedeller på citrongræsspyd","Hovedret","0-30 min","Se opskrift","Indisk kyllingegryde med røde linser, perlebyg og creme fraiche","Hovedret","30-60 min","Se opskrift","Julemarineret andebryst","Hovedret","90-120 min","Se opskrift","Grisemørbrad med forårsløg og asparges","Hovedret","30-60 min","Se opskrift","Kyllingebrystfileter med squash og spinat i pa