n","amount":150,"unit":"g champignoner rengjorte i halve","text":"150 g champignoner rengjorte i halve"},{"raavare_id":"ing_ris","amount":null,"unit":null,"text":"salt og friskkværnet peber"},{"raavare_id":null,"amount":3,"unit":"dl rødvin","text":"3 dl rødvin"},{"raavare_id":null,"amount":300,"unit":"ml (3 dl) hønsefond","text":"300 ml (3 dl) hønsefond"},{"raavare_id":"ing_loeg","amount":2,"unit":"fed hvidløg i skiver","text":"2 fed hvidløg i skiver"},{"raavare_id":"ing_ris","amount":4,"unit":"frisk timian","text":"4 frisk timian"},{"raavare_id":null,"amount":null,"unit":null,"text":"fintsnittet bladselleri"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3JpbGxldCBmbMO', 'Grillet flæskestegssandwich', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/grillet-flaskestegssandwich/4596839.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["Tilberedning","1.","Gnid flæskestegen med salt og peber, og grill den ved indirekte varme, eller steg den i ovnen i 45 min. til 1 time ved 200 °C, eller til den har en centrumtemperatur på 74 °C.","2.","Skær stegen i skiver.","3.","Snit kålen fint, og bland med revet gulerod og ærteskud.","4.","Vend salaten sammen med olivenolie og hvidvinseddike, og krydr med lidt salt og peber.","5.","Lun burgerbollerne, og smør dem med sriracha mayo.","6.","Kom 1-2 skiver flæskesteg i hver burger, og top med salat og syltede agurker.","Grill","SPISETID opskrift","Sandwich","Forår","Sommer","Svin","Næringsindhold:","Energiindhold for hele retten:","17697 kj / 4227 kcal","Næringsindhold pr. 100g","948 kj / 227 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.9 g","Protein:\t20.9 %\t11.7 g","Kulhydrat:\t13.7 %\t7.6 g","Fedt:\t65.4 %\t16.8 g","Alkohol:\t0 %\t0.0 g","20 stemmer","Bedøm opskriften","Relaterede opskrifter","Grillede pølser med knust agurkesalat og grov ærtehummus","Frokost","30-60 min","Se opskrift","Grillspyd med brunchpølser og grønt","Tilbehør","30-60 min","Se opskrift","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_extra_14","amount":1,"unit":"kg flæskesteg","text":"1 kg flæskesteg"},{"raava