k salt"},{"raavare_id":"ing_extra_31","amount":1,"unit":"dl olivenolie","text":"1 dl olivenolie"},{"raavare_id":"ing_extra_43","amount":100,"unit":"g rugbrødschips med salt som tilbehør","text":"100 g rugbrødschips med salt som tilbehør"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_VMOmcnRlIG1lZCB', 'Tærte med laks, Anicia linser og spinat', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/tarte-laks-anicia-linser-spinat/17106490.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Skyl og kog Anicia linserne i rigeligt letsaltet vand i 20-25 minutter. Hæld vandet fra linserne, og stil dem til side.","Tærtedej","1.","Bland ærtemel og salt i en skål.","2.","Med hænderne smuldres smørret heri.","3.","Tilsæt cremefraiche og rør det hele godt sammen med en ske.","4.","Smør et tærtefad med smagsneutral olie eller evt. smør.","5.","Rul dejen ud på et stykke bagepapir med en kagerulle, eller brug fingrene til at trykke dejen direkte ud i den smurte tærteform.","6.","Prik små huller i dejen med en gaffel.","7.","Forbag tærtedejen i ovnen i 5 minutter ved 175 grader varmluft.","Tærtefyld","1.","Fjern skindet fra laksen og skær den i mindre stykker.","2.","Hak hvidløg fint og skyl spinaten.","3.","Steg spinat og hvidløg på en varm pande i lidt olie så spinaten falder sammen.","4.","Pisk æg, cremefraiche, salt og peber sammen i en skål.","5.","Fordel de kogte Anicia linser, spinat og laks i den forbagte tærtedej, og hæld æggemassen over.","6.","Bag tærten i 20-25 min ved 175 grader varmluft til den er gylden og fast.","7.","Vi siger tak: Opskriften er udviklet af Pure Dansk.","Tærter","Fisk og skaldyr","Hovedret","Næringsindhold:","Energiindhold for hele retten:","9939 kj / 2374 kcal","Næringsindhold pr. 100g","787 kj / 188 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.3 g","Protein:\t17.6 %\t8.1 g","Kulhydrat:\t1.6 %\t0.8 g","Fedt:\t80.8 %\t17.2 g","Alkohol:\t0 %\t0.0 g","6 stemmer","Bedøm opskriften","Relaterede opskrifter","Laksetærte med broccoli og asparges","Hovedret","30-60 min","Se opskrift","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":null,"amount":200,"unit":"g ærtemel","text":"200 g ærtemel"},{"raavare_id":"ing_cremefraiche","amount":1,"unit":"dl creme fraiche 38% (eller anden fedtprocent)","text":"1 dl creme fraiche 38% (eller anden fedtprocent)"},{"raavare_id":null,"amount":100,"unit":"g smør","text":"100 g smør"},{"raavare_id":"ing_extra_43","amount":null,"unit":null,"text":"salt"},{"raavare_id":null,"amount":0.5,"unit":"dl tørrede anicia linser","text":"0.5 dl tørrede anicia linser"},{"raavare_id":null,"amount":300,"unit":"g ferske laks","text":"300 g ferske laks"},{"raavare_id":"ing_aeg","amount":5,"unit":"æg","text":"5 æg"},{"raavare_id":"ing_cremefraiche","amount":1,"unit":"dl creme fraiche 38% (eller anden fedtprocent)","text":"1 dl creme fraiche 38% (eller anden fedtprocent)"},{"raavare_id":"ing_ris","amount":200,"unit":"g frisk spinat","text":"200 g frisk spinat"},{"raavare_id":"ing_loeg","amount":1,"unit":"fed hvidløg","text":"1 fed hvidløg"},{"raavare_id":"ing_extra_43","amount":null,"unit":null,"text":"salt og peber"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_VHJhZGl0aW9uZWx', 'Traditionelle æbleskiver med kanel og æbletern', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/traditionelle-aebleskiver-kanel-og-aebletern/1687672909.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Pisk æg skummende sammen med sukker og kærnemælk.","2.","Bland mel med kardemomme og natron og rør det i dejen, så der ingen klumper er.","3.","Vend æbletern med citronsaft og kanel.","4.","Steg æbleskiverne i smør i en æbleskivepande.","5.","Fyld hullerne 2/3 op og kom et stykke æble i hver.","6.","Vend dem først en kvart omgang og så resten af vejen, så sikrer du flotte runde æbleskiver.","7.","Drys med flormelis ved servering.","Kager","Søde sager","Brød og kager","Jul","Vinter","Næringsindhold:","Energiindhold for hele retten:","5845 kj / 1396 kcal","Næringsindhold pr. 100g","570 kj / 136 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.3 g","Protein:\t15 %\t5.0 g","Kulhydrat:\t73.9 %\t24.8 g","Fedt:\t11.1 %\t1.7 g","Alkohol:\t0 %\t0.0 g","148 stemmer","Bedøm opskriften","Relaterede opskrifter","Sirupskage med valnødder og kanelglasur","Brød og kager","60-90 min","Se opskrift","Mormors glutenfri brunkager","Brød og kager","60-90 min","Se opskrift","Grove æbleskiver med ingefær og citrus","Brød og kager","0-30 min","Se opskrift","Honninghjerter","Brød og kager","60-90 min","Se opskrift","Mandelkage med portvinspærer","Brød og kager","60-90 min","Se opskrift","Gammeldags hjemmebagte pebernødder","Brød og kager","0-30 min","Se opskrift","Cheesecake med Øllingegaard Vinterkoldskål","Brød og kager","120+ min","Se opskrift","Glutenfrie æbleskiver","Brød og kager","0-30 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_aeg","amount":2,"unit":"æg","text":"2 æg"},{"raavare_id":"ing_extra_30","amount":2,"unit":"spsk sukker","text":"2 spsk sukker"},{"raavare_id":"ing_extra_26","amount":5,"unit":"dl kærnemælk","text":"5 dl kærnemælk"},{"raavare_id":"ing_extra_29","amount":250,"unit":"g hvedemel","text":"250 g hvedemel"},{"raavare_id":null,"amount":0.5,"unit":"tsk stødt kardemomme","text":"0.5 tsk stødt kardemomme"},{"raavare_id":null,"amount":1,"unit":"tsk natron","text":"1 tsk natron"},{"raavare_id":"ing_aeble","amount":1,"unit":"æble i små tern","text":"1 æble i små tern"},{"raavare_id":"ing_ris","amount":1,"unit":"tsk friskpresset citronsaft","text":"1 tsk friskpresset citronsaft"},{"raavare_id":"ing_kanel","amount":1,"unit":"tsk stødt kanel","text":"1 tsk stødt kanel"},{"raavare_id":null,"amount":null,"unit":null,"text":"smør til stegning"},{"raavare_id":null,"amount":1,"unit":"spsk flormelis til drys","text":"1 spsk flormelis til drys"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3LDpnNrYXItLCD', 'Græskar-, æble- og klementinchutney', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/graeskar-aeble-og-klementinchutney/4078729564.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Pil løget og skær det i skiver.","2.","Hak hvidløg, ingefær og chili fint.","3.","Vask græskarret grundigt, så skrællen kan bruges.","4.","Start med at halvere græskarret og fjern kernerne med en spiseske.","5.","Skær herefter græskarret ud i tern, ca. 2x2 cm og sæt til side.","6.","Halvér æbler, fjern kernehuset, og skær dem ud i tern.","7.","Del klementinerne i både og halvér dem.","8.","Sæt også æbler og klementiner til side.","9.","Knus sennepskorn, korianderfrø og fennikelfrø i en morder, og rist dem af i en gryde.","10.","Hæld olie i gryden sammen med de øvrige ingredienser på nær klementinerne.","11.","Lad det stege i 5 minutter.","12.","Tilsæt vand, og lad det koge i 5 minutter, inden æbleeddiken tilsættes.","13.","Lad chutneyen koge ved svag varme i 45 minutter.","14.","Vend klementinerne i den lune chutney og hæld den på skoldede syltetøjsglas.","15.","Sæt chutneyen på køl og lad den stå i minimum et døgn, inden den spises.","16.","Tip: Sørg for at skolde glassene, så chutneyen kan holde i flere måneder.","Tilbehør","Næringsindhold:","Energiindhold for hele retten:","2199 kj / 525 kcal","Næringsindhold pr. 100g","164 kj / 39 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.2 g","Protein:\t6.5 %\t0.6 g","Kulhydrat:\t44.3 %\t4.3 g","Fedt:\t49.2 %\t2.2 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Slagterens bearnaisesmør","Tilbehør","0-30 min","Se opskrift","Kornblomstsalat med cremet hindbærdressing","Tilbehør","0-30 min","Se opskrift","Figenkompot","Tilbehør","0-30 min","Se opskrift","Stikkelsbær chutney til ost","Tilbehør","30-60 min","Se opskrift","Kartoffelspiraler med salsa verde","Tilbehør","30-60 min","Se opskrift","Ristet rosenkål og butternut squash med bacon og granatæble","Tilbehør","30-60 min","Se opskrift","Honningsyltede nødder og rosiner","Snacks","0-30 min","Se opskrift","Aspargessalat med rygeostcreme, radiser og urtedressing","Forret","0-30 min","Se opskrift","Klassisk karrysild","Tilbehør","0-30 min","Se opskrift","Quinoasalat med ristede rødbeder, kål og sesamdressing","Tilbehør","0-30 min","Se opskrift","Glutenfri focaccia med græskar, feta og rosmarin","Tilbehør","90-120 min","Se opskrift","Indisk rissalat med kylling og chutney","Snacks","0-30 min","Se opskrift","Krebsehaler med spicy guacamole","Snacks","0-30 min","Se opskrift","Andeleverpaté med salvie","Tilbehør","0-30 min","Se opskrift","Jalapeño poppers med bacon og cheddar","Forret","30-60 min","Se opskrift","Julerødkålen","Tilbehør","0-30 min","Se opskrift","Syltede æblebåde med rosmarin og chili","Tilbehør","0-30 min","Se opskrift","Yoghurt dressing til salat","Tilbehør","0-30 min","Se opskrift","Grillet salat med Cardini’s Caesar dressing","Tilbehør","0-30 min","Se opskrift","Aspargeskartofler med granatæblekerner og sprød parmaskinke","Tilbehør","30-60 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_loeg","amount":3,"unit":"fed hvidløg","text":"3 fed hvidløg"},{"raavare_id":"ing_loeg","amount":1,"unit":"løg","text":"1 løg"},{"raavare_id":"ing_ris","amount":50,"unit":"g frisk ingefær","text":"50 g frisk ingefær"},{"raavare_id":null,"amount":1,"unit":"rød chilipeber","text":"1 rø