INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_QmFuYW4tY2hva29', 'Banan-chokoladepandekager', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/banan-chokoladepandekager/3062175351.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Bland bananmos med kakaomælk og pisk æg, sukker og vanilje i.","2.","Kom hvedemel, bagepulver, salt, kanel og chokolade i skålen og rør det hurtigt sammen – det skal ikke røres for meget.","3.","Lad dejen hvile i 10 min. og steg små pandekager i en pande med smør.","4.","Når der kommer små bobler på overfladen, skal de vendes.","5.","Server med skiver af banan og ahornsirup.","Frugt","SPISETID opskrift","Brød og kager","Dessert","Næringsindhold:","Energiindhold for hele retten:","6162 kj / 1472 kcal","Næringsindhold pr. 100g","791 kj / 189 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.3 g","Protein:\t10.1 %\t4.7 g","Kulhydrat:\t73.6 %\t34.3 g","Fedt:\t16.3 %\t3.5 g","Alkohol:\t0 %\t0.0 g","1 stemmer","Bedøm opskriften","Relaterede opskrifter","Sød crumble med blandede bær","Dessert","30-60 min","Se opskrift","Hjemmelavet flødeis med jordbær og krokant","Dessert","90-120 min","Se opskrift","Grillede bananer","Dessert","0-30 min","Se opskrift","Ricotta kage med chokolade og appelsin","Dessert","0-30 min","Se opskrift","Blåbærdessert med pære og hvid chokolademousse","Dessert","30-60 min","Se opskrift","Galette med æbler, pære og Them ost","Dessert","30-60 min","Se opskrift","Æbleroser med marcipan","Brød og kager","30-60 min","Se opskrift","Clafoutis med fersken","Brød og kager","30-60 min","Se opskrift","Tropisk cheesecake med ananas og malibu","Dessert","90-120 min","Se opskrift","Ispinde med kokos og jordbær","Dessert","0-30 min","Se opskrift","Hindbærkage toppet med flødeskum og friske hindbær","Dessert","60-90 min","Se opskrift","Mango mousse med mandelcrunch