INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_U3ZhbXBlLWLDuG5', 'Svampe-bønne stroganoff med filotopping', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/svampe-bonne-stroganoff-filotopping/45075023.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["Tilberedning","1.","Skær løg i små tern, hak hvidløget fint, og skær svampe i skiver.","2.","Varm olien, og svits løg sammen med svampe og timian.","3.","Krydr med lidt salt og peber.","4.","Tilsæt tomatpuré og paprika.","5.","Kom bønnerne inkl. den væde, de ligger i, sammen med sojasauce og fløde.","6.","Lad retten simre i 10 min., og jævn så saucen med majsstivelse, rørt op i lidt vand.","7.","Kom stroganoffen over i et ovnfast fad.","8.","Rul filodejen ud.","9.","Pensl hvert ark med lidt smør, krøl det lidt sammen, og læg det oven på stroganoffen.","10.","Bag retten i ovnen i 15-20 min. ved 180 °C.","SPISETID opskrift","Frokost","Hovedret","Næringsindhold:","Energiindhold for hele retten:","10673 kj / 2549 kcal","Næringsindhold pr. 100g","569 kj / 136 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t4.0 g","Protein:\t15 %\t5.0 g","Kulhydrat:\t39.6 %\t13.2 g","Fedt:\t45.4 %\t7.0 g","Alkohol:\t0 %\t0.0 g","4 stemmer","Bedøm opskriften","Relaterede opskrifter","Flammkuchen – hvid pizza fra alsace med bacon, creme fraiche og løg","Hovedret","60-90 min","Se opskrift","Torskefilet med nødder","Hovedret","60-90 min","Se opskrift","Pølsehorn","Frokost","30-60 min","Se opskrift","Friske forårsruller med citrongræsgris","Hovedret","30-60 min","Se opskrift","Salat med grillet kyllingebryst, grillet avocado og ranchdressing","Forret","0-30 min","Se opskrift","Lammekølle braiseret med æblemost, hvidløg og sennep","Hovedret","60-90 min","Se opskrift","Kalkunrulle fyldt med parmaskinke og rosmarin serveret med polenta","Hovedret","0-30 min","Se opskrift","Spaghe