INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_TGFuZ3RpZHNzdGV', 'Langtidsstegt lammekølle med rosmarin & rodfrugter', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/langtidsstegt-lammekoelle-rosmarin-rodfrugter/2522482038.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Læg lammekøllen i et ovnfast fad og gnid den med olie, citronsaft og skal, salt og peber.","2.","Stik rosmarin og hvidløg ind i køllen, og læg den på en rist.","3.","Rens rodfrugter, løg og kartofler og skær dem i grove stykker.","4.","Vend dem med olivenolie, salt og peber og kom dem, sammen med vinen, i en badepande eller et ovnfast fad, der kan stå under risten med lammekøllen.","5.","Sæt det hele i ovnen og steg det ved 150° i ca. 3 timer.","6.","Tilsæt løbende fløden til rodfrugterne, så de ikke koger tørre.","7.","Skær køllen i skiver og server med rodfrugter og evt. lidt friskkogte, grønne bønner.","Lam","Påske","Hovedret","Næringsindhold:","Energiindhold for hele retten:","24285 kj / 5800 kcal","Næringsindhold pr. 100g","552 kj / 132 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.9 g","Protein:\t30.3 %\t9.8 g","Kulhydrat:\t16.5 %\t5.4 g","Fedt:\t50.9 %\t7.6 g","Alkohol:\t2.3 %\t0.4 g","2 stemmer","Bedøm opskriften","Relaterede opskrifter","Rødvinsbraiseret lammekølle med rosmarin og knuste kartofler med ærter","Hovedret","120+ min","Se opskrift","Lammemørbrad med chermoula og bulgursalat med dadler","Hovedret","30-60 min","Se opskrift","Lammekoteletter med sauterede peberfrugter","Hovedret","30-60 min","Se opskrift","Lammekølle med marokkansk rub","Hovedret","Se opskrift","Græsk lammekølle","Hovedret","60-90 min","Se opskrift","Lammekrone med citronglaserede ærter og porrer","Hovedret","30-60 min","Se opskrift","Lammekølle og Ratatouille","Hovedret","90-120 min","Se opskrift","Lammekrone med grøn yoghurtdressing og bulgursalat med kikærter og feta","Hovedret","30-60 min","Se opskrift","Grillet lammemørbrad med forårsgrønt og sauce","Hovedret","30-60 min","Se opskrift","Grillede lammekoteletter med garam masala, spicy karrykartofler og rød peberfrugtpuré","Hovedret","30-60 min","Se opskrift","Grillet lammekølle med couscous, tomater og asparges.","Hovedret","60-90 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_extra_6","amount":null,"unit":null,"text":"Skal og saft af 2 citroner (usprøjtede)"},{"raavare_id":null,"amount":1,"unit":"lammekølle","text":"1 lammekølle"},{"raavare_id":null,"amount":2,"unit":"rosmarinkviste","text":"2 rosmarinkviste"},{"raavare_id":"ing_loeg","amount":4,"unit":"fed hvidløg","text":"4 fed hvidløg"},{"raavare_id":"ing_extra_31","amount":2,"unit":"dl god olivenolie","text":"2 dl god olivenolie"},{"raavare_id":"ing_extra_43","amount":null,"unit":null,"text":"groft salt"},{"raavare_id":"ing_ris","amount":null,"unit":null,"text":"friskkværnet peber"},{"raavare_id":"ing_extra_3","amount":1,"unit":"kg kartoffel","text":"1 kg kartoffel"},{"raavare_id":"ing_loeg","amount":2,"unit":"løg","text":"2 løg"},{"raavare_id":"ing_extra_4","amount":4,"unit":"gulerødder","text":"4 gulerødder"},{"raavare_id":null,"amount":1,"unit":"persillerod","text":"1 persillerod"},{"raavare_id":"ing_extra_40","amount":2,"unit":"dl hvidvin","text":"2 dl hvidvin"},{"raavare_id":"ing_floede","amount":2,"unit":"dl Arla Karolines Køkken® Madlavningsfløde 15%","text":"2 dl Arla Karolines Køkken® Madlavningsfløde 15%"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_QnLDpm5kZW5kZSB', 'Brændende kærlighed med linser', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/brandende-karlighed-linser/1370491136.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["Tilberedning","1.","Skræl kartoflerne og skær dem i halve eller kvarte.","2.","Kog dem helt møre i usaltet vand og gem 1½ dl af kogevandet, inden det sigtes fra.","3.","Kom mælk og smør i en gryde og varm det op, til smørret smelter.","4.","Hæld blandingen over de varme kartofler og mos det sammen.","5.","Smag til med salt, peber og revet muskatnød.","6.","Skær løg i strimler og skær gulerødder i små stykker.","7.","Varm olivenolie og smør på en pande og steg løg og gulerødder ved middel varme i 20 min. til det begynder at brune.","8.","Sigt linserne og skyl dem med koldt vand.","9.","Kom dem på panden sammen med lidt salt og peber, timian og balsamico eddike.","10.","Steg videre i 5 min. og servér som topping over kartoffelmosen.","Grøntsager","SPISETID opskrift","Næringsindhold:","Energiindhold for hele retten:","8226 kj / 1965 kcal","Næringsindhold pr. 100g","389 kj / 93 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.9 g","Protein:\t9.7 %\t2.2 g","Kulhydrat:\t50.9 %\t11.6 g","Fedt:\t39.4 %\t4.2 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Kartoffelspiraler med salsa verde","Tilbehør","30-60 min","Se opskrift","Spaghetti bolognese","Hovedret","0-30 min","Se opskrift","Pakora med dip","Snacks","30-60 min","Se opskrift","Ristet rosenkål og butternut squash med bacon og granatæble","Tilbehør","30-60 min","Se opskrift","Aspargessalat med rygeostcreme, radiser og urtedressing","Forret","0-30 min","Se opskrift","Grillet oksemørbrad med grillet grønt og bearnaisedip","Hovedret","60-90 min","Se opskrift","Æg i cocotte med laks og g