INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_S2FsdmVjdWxvdHR', 'Kalveculotte med pocherede grøntsager og kapersmayonnaise', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/kalveculotte-pocherede-groentsager-og-kapersmayonnaise/1091642552.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Fjern sener og rids kalveculotten.","2.","Brun den af på en pande i smør.","3.","Krydr med salt, peber og rosmarin.","4.","Pak culotten ind i folie og langtidssteg den i ovn ved 100 grader° i ca. 2 timer.","5.","Tag culotten ud af ovnen og lad den gerne trække i 15 min. inden udskæring.","6.","Bland ingredienser til kapersmayonnaise sammen.","7.","Kog pocheringslagen op, lad den stå og simre lige under kogepunktet.","8.","Klargør alle grøntsagerne, skal være lange rustikke stykker.","9.","Kom asparges, gulerod, fennikel, squash og forårsløg i lagen, giv det 3 min.","10.","Grøntsagerne skal være sprøde.","11.","Afdryppes i sigte.","12.","Anret skiver af kalveculotte med de pocherede grøntsager og kapers mayonnaise.","Hovedret","Næringsindhold:","Energiindhold for hele retten:","13141 kj / 3139 kcal","Næringsindhold pr. 100g","437 kj / 104 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.9 g","Protein:\t27.4 %\t7.0 g","Kulhydrat:\t7.5 %\t1.9 g","Fedt:\t65.1 %\t7.7 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Flammkuchen – hvid pizza fra alsace med bacon, creme fraiche og løg","Hovedret","60-90 min","Se opskrift","Torskefilet med nødder","Hovedret","60-90 min","Se opskrift","Friske forårsruller med citrongræsgris","Hovedret","30-60 min","Se opskrift","Salat med grillet kyllingebryst, grillet avocado og ranchdressing","Forret","0-30 min","Se opskrift","Lammekølle braiseret med æblemost, hvidløg og sennep","Hovedret","60-90 min","Se opskrift","Kalkunrulle fyldt med parmaski