nit":"løg i både","text":"1 løg i både"},{"raavare_id":null,"amount":3,"unit":"laurbærblade","text":"3 laurbærblade"},{"raavare_id":null,"amount":25,"unit":"g smør","text":"25 g smør"},{"raavare_id":"ing_extra_43","amount":1,"unit":"tsk salt","text":"1 tsk salt"},{"raavare_id":"ing_extra_40","amount":3,"unit":"spsk hvidvinseddike","text":"3 spsk hvidvinseddike"},{"raavare_id":"ing_asparges","amount":150,"unit":"g grønne asparges","text":"150 g grønne asparges"},{"raavare_id":"ing_extra_4","amount":4,"unit":"gulerødder skåret på langs","text":"4 gulerødder skåret på langs"},{"raavare_id":"ing_fennikel","amount":1,"unit":"fennikel skåret i både på langs","text":"1 fennikel skåret i både på langs"},{"raavare_id":"ing_squash","amount":1,"unit":"grøn squash skåret på langs","text":"1 grøn squash skåret på langs"},{"raavare_id":"ing_loeg","amount":8,"unit":"forårsløg i halve","text":"8 forårsløg i halve"},{"raavare_id":"ing_mayonnaise","amount":2,"unit":"dl mayonnaise","text":"2 dl mayonnaise"},{"raavare_id":null,"amount":1,"unit":"tsk dijonsennep","text":"1 tsk dijonsennep"},{"raavare_id":"ing_kapers","amount":40,"unit":"g kapers grofthakket","text":"40 g kapers grofthakket"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_TW9ybW9ycyB2aW5', 'Mormors vintertarteletter', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/mormors-vintertarteletter/2334178314.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Kom kyllingen i en gryde, og dæk den med vand.","2.","Halvér løget, og kom det i gryden sammen med toppen af porren.","3.","Skær én gulerod groft, og kom i gryden.","4.","I starten dannes der skum på toppen af suppen.","5.","Skum dette af med en hulske.","6.","Kog kyllingen i 50 min. ved svag varme.","7.","Tag kyllingen op, og lad den køle så meget af, at skindet kan tages af.","8.","Sigt suppen.","9.","Du skal bruge 4 dl til tarteletfyldet.","10.","Resten kan du fryse – det kan f.eks. bruges til en suppe eller risotto.","11.","Pil kødet af skroget, og tag cirka 300 g til tarteletfyld.","12.","Del kødet i mindre stykker.","13.","Skræl den anden gulerod, og skær i små tern.","14.","Snit resten af porren i tynde skiver.","15.","Smelt smør i en gryde, og drys melet i.","16.","Steg det i et minut, og hæld så suppe i, mens der piskes.","17.","Kom fløde, gulerødder og porrer i, og krydr med salt og hvid peber.","18.","Lad grøntsagerne simre i suppen i 5 min.","19.","Tilsæt så kyllingekødet, og varm det igennem.","20.","Hak persillen, og kom den i.","21.","Servér i varme tarteletter.","Gryderet","SPISETID opskrift","Hovedret","Vinter","Næringsindhold:","Energiindhold for hele retten:","12875 kj / 3075 kcal","Næringsindhold pr. 100g","400 kj / 95 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.4 g","Protein:\t30.7 %\t7.2 g","Kulhydrat:\t6.6 %\t1.6 g","Fedt:\t62.7 %\t6.8 g","Alkohol:\t0 %\t0.0 g","1 stemmer","Bedøm opskriften","Relaterede opskrifter","Osso buco med rødvinssauce og fettuccini","Hovedret","120+ min","Se opskrift","Osso buco med fennikel, blomkål og appelsin","Hovedret","90-120 min","Se opskrift","Vildtragout med rødbeder og svampe","Hovedret","90-120 min","Se opskrift","Vildt bourgignon med kartoffel-jordskokkemos","Hovedret","120+ min","Se opskrift","Kylling tikka masala med kokos og spinat","Hovedret","30-60 min","Se opskrift","”Marry Me” gråærter","Hovedret","90-120 min","Se opskrift","Vintergryde med gulerødder, pastinak, kikærter og rosmarin","Hovedret","30-60 min","Se opskrift","Vildtgryde med chiligremolata","Hovedret","90-120 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":null,"amount":1,"unit":"kylling","text":"1 kylling"},{"raavare_id":null,"amount":1,"unit":"liter vand","text":"1 liter vand"},{"raavare_id":"ing_loeg","amount":1,"unit":"løg","text":"1 løg"},{"raavare_id":null,"amount":1,"unit":"porre","text":"1 porre"},{"raavare_id":"ing_extra_4","amount":2,"unit":"gulerødder","text":"2 gulerødder"},{"raavare_id":"ing_extra_43","amount":null,"unit":null,"text":"salt og hvid peber"},{"raavare_id":null,"amount":50,"unit":"g smør","text":"50 g smør"},{"raavare_id":"ing_extra_29","amount":3,"unit":"spsk hvedemel","text":"3 spsk hvedemel"},{"raavare_id":null,"amount":1,"unit":"dl piskefløde","text":"1 dl piskefløde"},{"raavare_id":null,"amount":4,"unit":"dl hønsekødssuppe","text":"4 dl hønsekødssuppe"},{"raavare_id":null,"amount":1,"unit":"dl kruspersille","text":"1 dl kruspersille"},{"raavare_id":null,"amount":null,"unit":null,"text":"tilbehør: lune tartelet"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_VMOmcnRlIG1lZCB', 'Tærte med rødbede, gedeost og rødløg', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/tarte-rodbede-gedeost-rodlog/3486233604.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Smør en tærteform på ca. 22-24 cm. med smør.","2.","Bland de to slags mel med salt og smuldr det kolde smør i med fingrene til det ligner grov rasp.","3.","Kom æggeblomme og en smule vand i og saml dejen.","4.","Den skal ikke æltes.","5.","Saml dejen til en kugle og tryk den lidt flad.","6.","Pak dejen ind i plastfolie og lad den hvile i køleskabet i 30 min.","7.","Rul dejen ud til en stor cirkel og kom den i tærteformen. Det er nemt at gøre det mellem to stykker bagepapir.","8.","Trim kanterne på tærten og dæk den med bagepapir.","9.","Kom bagebønner eller ris i for at veje ned og forbag tærtebunden i 15 min. ved 180 °C.","10.","Fjern bagebønner og bagepapir og bag tærten i yderligere 5 min. til den er let gylden.","11.","Til fyldet skrælles bederne, skæres i både og kommes i et ovnfast fad.","12.","Skær løgene i kvarte og kom dem i fadet med bederne.","13.","Dryp olivenolie over og krydr med lidt salt og peber.","14.","Bag grøntsagerne i 30 min. ved 200 °C.","15.","Læg beder og rødløg i den forbagte tærteform.","16.","Smuldr gedeosten i grove stykker og læg dem ned mellem grøntsagerne.","17.","Drys med timian.","18.","Rør æg sammen med piskefløde, creme fraiche og dijonsennep og krydr med lidt salt og peber.","19.","Hæld blandingen i tærteformen og bag tærten i ca. 30 min ved 180 °C til æggemassen har sat sig.","Tærter","SPISETID opskrift","Vegetar","Grøntsager","Frokost","Hovedret","Næringsindhold:","Energiindhold for hele retten:","11503 kj / 2747 kcal","Næringsindhold pr. 100g","789 kj / 189 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.6 g","Protein:\t9.4 %\t4.4 g","Kulhydrat:\t32.2 %\t14.9 g","Fedt:\t58.4 %\t12.5 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Pizza Bianca med courgetter, pesto og mozzarella","Frokost","90-120 min","Se opskrift","Kartoffelmad med béarnaise og balsamicobagte tomater","Madpakke","0-30 min","Se opskrift","Bønne burrito","Hovedret","0-30 min","Se opskrift","Krydret græskarsuppe","Frokost","30-60 min","Se opskrift","Wraps med stegte krydrede Ingrid ærter og grønt","Hovedret","120+ min","Se opskrift","Tærte med karamelliserede rødløg og blåskimmelost","Frokost","60-90 min","Se opskrift","Ramen med smilende æg, boghvedenudler og sprød topping","Hovedret","0-30 min","Se opskrift","Pocheret æg med grønne asparges, avocado og rugbrødsknas","Morgenmad & Brunch","0-30 min","Se opskrift","Grøntsagsmoussaka - vegansk fra Mia Sommer","Hovedret","60-90 min","Se opskrift","Nem tærte med græskar, feta og krydderurtedressing","Frokost","0-30 min","Se opskrift","Quinoasalat med ærter, asparges, feta og mynte","Tilbehør","0-30 min","Se opskrift","Cremet pasta med peberfrugter","Hovedret","0-30 min","Se opskrift","Cremet spaghetti med edamame, ærter og porre","Frokost","0-30 min","Se opskrift","Vegetarisk tex-mex gryde","Hovedret","0-30 min","Se opskrift","Veganske boller i cremet svampesauce og kartoffelpuré med ristet hvidløg","Hovedret","30-60 min","Se opskrift","Klassisk Lasagne med Anicia linser","Hovedret","60-90 min","Se opskrift","Kartoffelgalette med rosmarin-cremefraiche og purløg","Hovedret","30-60 min","Se opskrift","Svampestuvning med butterdejslåg","Hovedret","30-60 min","Se opskrift","Broccolitærte med cashewcreme - vegansk fra Mia Sommer","Hovedret","60-90 min","Se opskrift","Ratatouille med stracciatella & sprøde salater","Hovedret","0-30 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserk