INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_UmFtZW4gbWVkIHN', 'Ramen med smilende æg, boghvedenudler og sprød topping', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/ramen-smilende-ag-boghvedenudler-og-sprod-topping/3225438588.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Kog æggene i 8 minutter, og køl dem ned under rindende koldt vand.","2.","Kog boghvedenudlerne efter pakkens anvisning.","3.","Bring grønsagsbouillonen i kog, og tilsæt fløde.","4.","Smag suppen til med sojasauce.","5.","Fordel nudlerne i fire passende skåle.","6.","Snit spidskål og chili fint.","7.","Svits østershattene gyldne på panden i en smule olie.","8.","Kom enoki, østershatte, spidskål, gulerødder, chili og bønnespirer i skålene, og hæld den varme suppe over fyldet.","9.","Pil æggene, og skær dem i halve.","10.","Top hver suppe med to halve æg, og pynt til sidst med frisk koriander, et drys ristede sesamfrø og friskkværnet peber.","Grøntsager","Mellemøsten","Vegetar","Hovedret","Næringsindhold:","Energiindhold for hele retten:","7962 kj / 1902 kcal","Næringsindhold pr. 100g","351 kj / 84 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.1 g","Protein:\t20.1 %\t4.1 g","Kulhydrat:\t62.2 %\t12.9 g","Fedt:\t17.7 %\t1.7 g","Alkohol:\t0 %\t0.0 g","21 stemmer","Bedøm opskriften","Relaterede opskrifter","Karry ramen med ristede rodfrugter og kål","Frokost","30-60 min","Se opskrift","Rice bowl med mango, teriyakilaks og broccoli","Frokost","0-30 min","Se opskrift","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_aeg","amount":4,"unit":"æg","text":"4 æg"},{"raavare_id":null,"amount":400,"unit":"g boghvede nudler","text":"400 g boghvede nudler"},{"raavare_id":"ing_bouillon","amount":1,"unit":"liter grøntsagsbouillon","text":"1 liter grøntsagsbouillon"},{"raavare_id":null,"amount":2,"unit":"dl fløde","text":"2 dl fløde"},{"raavare_id":"ing_soja","amount":4,"unit":"spsk sojasauce","text":"4 spsk sojasauce"},{"raavare_id":"ing_spidskaal","amount":100,"unit":"g lilla spidskål","text":"100 g lilla spidskål"},{"raavare_id":"ing_ris","amount":1,"unit":"frisk chili","text":"1 frisk chili"},{"raavare_id":"ing_oestershatte","amount":100,"unit":"g østershatte","text":"100 g østershatte"},{"raavare_id":null,"amount":null,"unit":null,"text":"lidt olie til stegning"},{"raavare_id":null,"amount":100,"unit":"g enokisvampe","text":"100 g enokisvampe"},{"raavare_id":"ing_boennespirer","amount":80,"unit":"g bønnespirer","text":"80 g bønnespirer"},{"raavare_id":"ing_ris","amount":null,"unit":null,"text":"ristede sesamfrø"},{"raavare_id":"ing_ris","amount":null,"unit":null,"text":"friskkværnet peber"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_QmFndCBrYXJ0b2Z', 'Bagt kartoffel med linsechili, korianderdressing og ost', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/bagt-kartoffel-med-linsechili-korianderdressing-og-ost/2216890339.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Vask kartoflerne, og dup dem tørre.","2.","Prik dem et par steder med en kødnål, og pak dem ind i alufolie.","3.","Bag dem på en rist i ovnen i 1 time og 15 min. ved 200 °C.","4.","Skær løg i små tern, og hak hvidløget fint.","5.","Riv guleroden.","6.","Varm olien i en gryde, og svits løg og gulerødder i 4 min.","7.","Tilsæt hvidløg, og steg videre i 1 minut.","8.","Kom spidskommen, paprika og røget paprika i sammen med tomatpuré, og steg det i 1 minut.","9.","Tilsæt vand og linser, og kom lidt salt og peber i.","10.","Lad retten simre i 15 min.","11.","Blend koriander og fraiche sammen, og smag til med salt og peber.","12.","Tag kartoflerne ud af folien, og skær et snit ned gennem toppen af skindet, så kartoflen kan åbnes.","13.","Fyld linsechili i, og top med dressing, revet ost, hakket koriander og chili.","Grøntsager","SPISETID opskrift","Hovedret","Næringsindhold:","Energiindhold for hele retten:","8820 kj / 2107 kcal","Næringsindhold pr. 100g","405 kj / 97 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t1.7 g","Protein:\t21.1 %\t5.0 g","Kulhydrat:\t53.5 %\t12.7 g","Fedt:\t25.4 %\t2.8 g","Alkohol:\t0 %\t0.0 g","24 stemmer","Bedøm opskriften","Relaterede opskrifter","Spaghetti bolognese","Hovedret","0-30 min","Se opskrift","Ristet rosenkål og butternut squash med bacon og granatæble","Tilbehør","30-60 min","Se opskrift","Grillet oksemørbrad med grillet grønt og bearnaisedip","Hovedret","60-90 min","Se opskrift","Grillede koteletter med mojo-dip og grillet grønt","Hovedret","30-60 min","Se opskrift","Wok med hakket okse, broccoli og hoisinsauce","Hovedret","0-30 min","Se opskrift","Chicken Alfredo med bacon, broccoli og frisk pasta","Hovedret","0-30 min","Se opskrift","Crumble med pasta og ratatouille","Hovedret","30-60 min","Se opskrift","Asiatisk nudelsalat med kødboller","Hovedret","30-60 min","Se opskrift","Pizza Bianca med courgetter, pesto og mozzarella","Frokost","90-120 min","Se opskrift","Bagt græskarsuppe med ristede kerner","Hovedret","60-90 min","Se opskrift","Rødkålssalat med granatæble, rødbede, vindruer og valnødder","Hovedret","30-60 min","Se opskrift","Burger med pestomarinerede grøntsager og aioli","Hovedret","0-30 min","Se opskrift","Grøntsagssuppe med syltede rødløg og crispy kålchips","Hovedret","30-60 min","Se opskrift","Rødkålssalat med ristede valnødder, klementiner og spidskål","Hovedret","30-60 min","Se opskrift","Grillet blomkål med kogte nye kartofler, urteyoghurt og brunet sojasmør","Hovedret","Se opskrift","Piccata af fadkoteletter med ansjosristet broccoli","Hovedret","0-30 min","Se opskrift","Flæskesteg med rodfrugter i fad","Hovedret","60-90 min","Se opskrift","Kartoffelmos med cremet svampegryde og grønkålssalat","Hovedret","30-60 min","Se opskrift","Texas-style bbq mørbrad med grillede majs","Hovedret","0-30 min","Se opskrift","Pasta med røget laks i cremet sauce med broccoli","Hovedret","0-30 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_loeg","amount":1,"unit":"løg","text":"1 løg"},{"raavare_id":"ing_extra_3","amount":4,"unit":"bagekartofler","text":"4 bagekartofler"},{"raavare_id":"ing_loeg","amount":1,"unit":"fed hvidløg","text":"1 fed hvidløg"},{"raavare_id":null,"amount":1,"unit":"gulerod","text":"1 gulerod"},{"raavare_id":"ing_extra_31","amount":1,"unit":"spsk olivenolie","text":"1 spsk olivenolie"},{"raavare_id":"ing_spidskommen","amount":1,"unit":"tsk stødt spidskommen","text":"1 tsk stødt spidskommen"},{"raavare_id":"ing_extra_45","amount":1,"unit":"tsk paprika","text":"1 tsk paprika"},{"raavare_id":"ing_extra_45","amount":0.5,"unit":"tsk røget paprika","text":"0.5 tsk røget paprika"},{"raavare_id":"ing_extra_1","amount":2,"unit":"spsk koncentreret tomatpuré","text":"2 spsk koncentreret tomatpuré"},{"raavare_id":null,"amount":4,"unit":"dl vand","text":"4 dl vand"},{"raavare_id":"ing_extra_27","amount":150,"unit":"g tørrede røde linser","text":"150 g tørrede røde linser"},{"raavare_id":"ing_extra_43","amount":1,"unit":"knivspids salt og peber","text":"1 knivspids salt og peber"},{"raavare_id":"ing_ris","amount":1,"unit":"håndfuld frisk koriander + ekstra til servering","text":"1 håndfuld frisk koriander + ekstra til servering"},{"raavare_id":"ing_cremefraiche","amount":2,"unit":"dl økologisk creme fraiche 9%","text":"2 dl økologisk creme fraiche 9%"},{"raavare_id":null,"amount":150,"unit":"g revet mozzarellaost","text":"150 g revet mozzarellaost"},{"raavare_id":"ing_ris","amount":1,"unit":"frisk chili","text":"1 frisk chili"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_RGhhbA', 'Dhal', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/dhal/3890328785.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Svits krydderier, løg og hvidløg i en gryde i et par minutter.","2.","Brug lidt vand eller olie, så det ikke brænder på.","3.","Skyl linserne og put dem i gryden sammen med salt, sukker, tomatpure og vand.","4.","Lad retten koge i 25 minutter under låg.","5.","Smag til med salt og chili.","6.","Server retten sammen med ris og eksempelvis frisk koriander, mangochutney, ananasstykker, peanuts, tzatziki og brød.","Forret","Tilbehør","Gryderet","Næringsindhold:","Energiindhold for hele retten:","6566 kj / 1568 kcal","Næringsindhold pr. 100g","414 kj / 99 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t2.4 g","Protein:\t28.8 %\t7.0 g","Kulhydrat:\t65.2 %\t15.9 g","Fedt:\t6 %\t0.7 g","Alkohol:\t0 %\t0.0 g","7 stemmer","Bedøm opskriften","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":null,"amount":150,"unit":"g tørrede grønne linser","text":"150 g tørrede grønne linser"},{"raavare_id":"ing_extra_27","amount":250,"unit":"g tørrede røde linser","text":"250 g tørrede røde linser"},{"raavare_id":"ing_loeg","amount":1,"unit":"løg, hakket","text":"1 løg, hakket"},{"raavare_id":"ing_loeg","amount":4,"unit":"fed hvidløg, pressede","text":"4 fed hvidløg, pressede"},{"raavare_id":"ing_ris","amount":2,"unit":"tsk frisk koriander","text":"2 tsk frisk koriander"},{"raavare_id":"ing_spidskommen","amount":2,"unit":"tsk stødt spidskommen","text":"2 tsk stødt spidskommen"},{"raavare_id":"ing_chili","amount":2,"unit":"tsk stødt gurkemeje & evt. chilipulver","text":"2 tsk stødt gurkemeje & evt. chilipulver"},{"raavare_id":"ing_extra_43","amount":2,"unit":"tsk salt","text":"2 tsk salt"},{"raavare_id":"ing_extra_30","amount":1,"unit":"tsk sukker","text":"1 tsk sukker"},{"raavare_id":"ing_extra_1","amount":70,"unit":"g koncentreret tomatpuré","text":"70 g koncentreret tomatpuré"},{"raavare_id":null,"amount":1,"unit":"liter vand","text":"1 liter vand"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3LDuG5rw6Vsc3N', 'Grønkålssalat med klementindressing', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/groenkaalssalat-klementindressing/3333176500.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Hak grønkålen groft og skær æbler i tynde både.","2.","Kom i en skål sammen med rosiner og knuste valnødder.","3.","Rør en dressing af ahornsirup, olivenolie og klementinsaft.","4.","Smag til med salt og peber og vend dressingen i salaten.","Grøntsager","Tilbehør","Frokost","Salater","Næringsindhold:","Energiindhold for hele retten:","4795 kj / 1145 kcal","Næringsindhold pr. 100g","664 kj / 159 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t3.3 g","Protein:\t7.8 %\t3.0 g","Kulhydrat:\t33 %\t12.9 g","Fedt:\t59.2 %\t10.6 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Ristet rosenkål og butternut squash med bacon og granatæble","Tilbehør","30-60 min","Se opskrift","Aspargessalat med rygeostcreme, radiser og urtedressing","Forret","0-30 min","Se opskrift","Tomatsalsa med lime og koriander","Tilbehør","0-30 min","Se opskrift","Lun broccolisalat med æbler, syltet rødløg, parmesan og nødder","Tilbehør","0-30 min","Se opskrift","Spicy asiatisk agurkesalat","Snacks","0-30 min","Se opskrift","Spinatsalat med blomkål og ristede pinjekerner","Tilbehør","0-30 min","Se opskrift","Grønne asparges med yoghurt og brunet smør med kapers","Tilbehør","0-30 min","Se opskrift","Grillet squash caprese salat","Tilbehør","30-60 min","Se opskrift","Avocadosalat med blåbær, fetaost, saltristede mandler og mynte-limedressing","Tilbehør","0-30 min","Se opskrift","Pastasalat med grønne asparges og bønner og persillepesto med skyr","Frokost","0-30 min","Se opskrift","Quinoasalat med ærter, asparges, feta og mynte","Tilbehør","0-30 min","Se ops