INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3JpbGxldCBjdWx', 'Grillet culotte med hvidløgs-pebermix', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/grillet-culotte-hvidloegs-pebermix/1218520422.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Rids fedtet på culotten.","2.","Kom hvidløg, begge slags peber, timian og salt i en morter og mos det sammen til en grov pasta.","3.","Smør blandingen på toppen af culotten.","4.","Grill culotten ved indirekte varme i 40-45 min. til den har en kernetemperatur på 55°C.","5.","Lad kødet hvile i 10 min før det skæres i skiver.","SPISETID opskrift","Hovedret","Næringsindhold:","Energiindhold for hele retten:","15418 kj / 3683 kcal","Næringsindhold pr. 100g","888 kj / 212 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.2 g","Protein:\t36.6 %\t19.1 g","Kulhydrat:\t0.9 %\t0.5 g","Fedt:\t62.5 %\t15.0 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Flammkuchen – hvid pizza fra alsace med bacon, creme fraiche og løg","Hovedret","60-90 min","Se opskrift","Torskefilet med nødder","Hovedret","60-90 min","Se opskrift","Friske forårsruller med citrongræsgris","Hovedret","30-60 min","Se opskrift","Salat med grillet kyllingebryst, grillet avocado og ranchdressing","Forret","0-30 min","Se opskrift","Lammekølle braiseret med æblemost, hvidløg og sennep","Hovedret","60-90 min","Se opskrift","Kalkunrulle fyldt med parmaskinke og rosmarin serveret med polenta","Hovedret","0-30 min","Se opskrift","Spaghetti bolognese","Hovedret","0-30 min","Se opskrift","Tærte med laks, Anicia linser og spinat","Hovedret","30-60 min","Se opskrift","Fladbrød med edamamehummus og spicy stegte kartofler","Hovedret","30-60 min","Se opskrift","Lasagne med gris, fennikel og ricotta","Hovedret","30-60 min","Se opskrift","Kyllingedeller på citrongræsspyd","