INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3VsZXJvZHNib2x', 'Gulerodsboller', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/gulerodsboller1/3318067509.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Der bliver ca. 16-18 boller.","2.","Lun kærnemælken og rør gæren ud.","3.","Rør groftrevne gulerødder og de øvrige ingredienser i dejen - hold lidt af melet tilbage.","4.","Sørg for at dejen ikke bliver for fast.","5.","Lad dejen hæve lunt, tildækket ca. 1 time.","6.","Sæt store spiseskefulde af dejen på plader med bagepapir og lad bollerne efterhæve 8-10 minutter.","7.","Bag bollerne gyldne og sprøde ved 200 grader i 20-25 minutter, og afkøl på en bagerist. Opskrift og styling: Udviklet af Vibeke Lehn.","Brød og kager","Brød og boller","Næringsindhold:","Energiindhold for hele retten:","20620 kj / 4925 kcal","Næringsindhold pr. 100g","769 kj / 184 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t4.3 g","Protein:\t13.8 %\t6.2 g","Kulhydrat:\t76.6 %\t34.6 g","Fedt:\t9.6 %\t2.0 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Snoet persillebrød med hvidhvede og øl","Brød og kager","60-90 min","Se opskrift","Fougasse med oliven og timian","Brød og kager","0-30 min","Se opskrift","Snoet hvidløgsbrød med urter","Brød og kager","0-30 min","Se opskrift","Rustikt grydebrød med havre","Tilbehør","30-60 min","Se opskrift","Ølandshvedebrød med kefir","Brød og kager","90-120 min","Se opskrift","Citronscones med hindbærcreme","Brød og kager","0-30 min","Se opskrift","Fastelavnsboller med vaniljecreme, fløde og syltetøj","Brød og kager","30-60 min","Se opskrift","Laktosefri flækkede fastelavnsboller","Brød og kager","0-30 min","Se opskrift","Langtidshævet foccacia med druer og rosmarin","Snacks","0-30 min","Se opskrift","Langtidshævet foccacia med Prima Donna og rødløg