INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_SmFsYXBlw7FvIHB', 'Jalapeño poppers med bacon og cheddar', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/jalapeno-poppers-bacon-og-cheddar/2595229384.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Steg bacon sprødt i en tør pande, og hak det fint.","2.","Bland bacon sammen med flødeost, cheddar, paprika og purløg.","3.","Flæk jalapeños, og brug en teske til at skrabe frøene ud.","4.","Fyld med flødeostblandingen og drys rasp på toppen.","5.","Bages i 10-12 min. ved 200°C og spises lune.","Grøntsager","Forret","Tilbehør","SPISETID opskrift","Næringsindhold:","Energiindhold for hele retten:","4352 kj / 1039 kcal","Næringsindhold pr. 100g","1064 kj / 254 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.9 g","Protein:\t17.4 %\t10.9 g","Kulhydrat:\t7.6 %\t4.7 g","Fedt:\t75 %\t21.6 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Kartoffelspiraler med salsa verde","Tilbehør","30-60 min","Se opskrift","Ristet rosenkål og butternut squash med bacon og granatæble","Tilbehør","30-60 min","Se opskrift","Aspargessalat med rygeostcreme, radiser og urtedressing","Forret","0-30 min","Se opskrift","Tomatsalsa med lime og koriander","Tilbehør","0-30 min","Se opskrift","Kastanjer med porre, bacon og grønne bønner","Tilbehør","30-60 min","Se opskrift","Kartoffelbåde med spicy gremolata","Tilbehør","0-30 min","Se opskrift","Grønkålssalat med klementindressing","Tilbehør","0-30 min","Se opskrift","Grøntsagsstænger med peberfrugt-flødeostdip","Madpakke","0-30 min","Se opskrift","Nem minestrone med chorizo, bønner og pasta","Forret","0-30 min","Se opskrift","Grillet peberfrugt chutney","Tilbehør","30-60 min","Se opskrift","Lun broccolisalat med æbler, syltet rødløg, parmesan og nødder","Tilbehør","0-30 min","Se opskrift","Ærtesu