INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_RnVsZGtvcm5zcGV', 'Fuldkornspebernødder med chokoladebund', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/fuldkornspebernoedder-chokoladebund/683091809.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Ca. 40 stk.","2.","Bland krydderierne med bagepulver og begge slags mel.","3.","Smuldr smørret i melblandingen, og kom rørsukker i.","4.","Saml dejen med piskefløde, og ælt den sammen.","5.","Tril dejen til pølser, og skær dem i stykker på ca. 2 cm.","6.","Tril dem til kugler, og læg dem på bageplader med bagepapir.","7.","Bag pebernødderne ca. 8 min. ved 180°C.","8.","Lad dem køle af.","9.","Smelt chokoladen over vandbad, og dyp bunden af hver pebernød deri.","10.","Lad dem køle af på bagepapir.","11.","Opbevares i kagedåse i op til 10 dage.","SPISETID opskrift","Småkager","Brød og kager","Jul","Næringsindhold:","Energiindhold for hele retten:","11314 kj / 2702 kcal","Næringsindhold pr. 100g","1785 kj / 426 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t3.8 g","Protein:\t5.3 %\t5.5 g","Kulhydrat:\t50.4 %\t52.9 g","Fedt:\t44.3 %\t21.4 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Appelsin-chokolade specier","Brød og kager","0-30 min","Se opskrift","Småkage hack","Brød og kager","0-30 min","Se opskrift","Honninghjerter","Brød og kager","60-90 min","Se opskrift","Rudolf småkager","Brød og kager","30-60 min","Se opskrift","Gammeldags hjemmebagte pebernødder","Brød og kager","0-30 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":null,"amount":1,"unit":"tsk stødt ingefær","text":"1 tsk stødt ingefær"},{"raavare_id":"ing_kanel","amount":0.5,"unit":"tsk stødt kanel","text":"0.5 tsk stødt kanel"},{"raavare_id":null,"amount":0.5,"unit":"tsk stødt hvid peber","text":"0.5 tsk stødt hvid peber"},{"raavare_id":null,"amount":0.5,"unit":"tsk stødt nellike","text":"0.5 tsk stødt nellike"},{"raavare_id":null,"amount":0.5,"unit":"tsk stødt kardemomme","text":"0.5 tsk stødt kardemomme"},{"raavare_id":"ing_bagepulver","amount":0.5,"unit":"tsk bagepulver","text":"0.5 tsk bagepulver"},{"raavare_id":"ing_extra_29","amount":150,"unit":"g hvid hvedemel","text":"150 g hvid hvedemel"},{"raavare_id":"ing_extra_29","amount":100,"unit":"g hvedemel","text":"100 g hvedemel"},{"raavare_id":null,"amount":100,"unit":"g koldt smør","text":"100 g koldt smør"},{"raavare_id":"ing_extra_30","amount":125,"unit":"g rørsukker","text":"125 g rørsukker"},{"raavare_id":null,"amount":0.5,"unit":"dl Arla Karolines Køkken® Piskefløde 38%","text":"0.5 dl Arla Karolines Køkken® Piskefløde 38%"},{"raavare_id":"ing_mork_chokolade","amount":100,"unit":"g mørk chokolade","text":"100 g mørk chokolade"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_Q29xIGF1IHZpbg', 'Coq au vin', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/coq-au-vin-0/2836405550.jpeg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Varm smøret op i en sautepande til det bruser.","2.","Kom de 8 stykker kylling i og brun dem godt på alle sider, krydr med salt og peber.","3.","Tag derefter kyllingen op på et fad.","4.","Brun bacon, skalotteløg og champignons til det er gyldent i cirka 5 minutter.","5.","Kom vin på og lad det komme i kog.","6.","Tilsæt derefter hønsebouillon og lad det simre i 5 minutter.","7.","Kom de brunede kyllingestykker, hvidløg og timian i et ovnfast fad, hæld bacon og vin blandingen over og steges i ovn ved 160 grader i 35 minutter til kyllingen er mør.","8.","Smages til med salt, peber og frisk timian.","9.","Pynt med snittet bladselleri.","Fjerkræ","Svin","Hovedret","Næringsindhold:","Energiindhold for hele retten:","15105 kj / 3608 kcal","Næringsindhold pr. 100g","606 kj / 145 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.5 g","Protein:\t33.3 %\t11.9 g","Kulhydrat:\t10.6 %\t3.8 g","Fedt:\t49.7 %\t8.1 g","Alkohol:\t6.4 %\t1.3 g","2 stemmer","Bedøm opskriften","Relaterede opskrifter","Friske forårsruller med citrongræsgris","Hovedret","30-60 min","Se opskrift","Kalkunrulle fyldt med parmaskinke og rosmarin serveret med polenta","Hovedret","0-30 min","Se opskrift","Lasagne med gris, fennikel og ricotta","Hovedret","30-60 min","Se opskrift","Kyllingedeller på citrongræsspyd","Hovedret","0-30 min","Se opskrift","Indisk kyllingegryde med røde linser, perlebyg og creme fraiche","Hovedret","30-60 min","Se opskrift","Julemarineret andebryst","Hovedret","90-120 min","Se opskrift","Grisemørbrad med forårsløg og asparges","Hovedret","30-60 min","Se opskrift","Kyllingebrystfileter med squash og spinat i pa