INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_UGFzdGEgUG9tb2R', 'Pasta Pomodoro', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/pasta-pomodoro/424675678.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Hak løg, hvidløg og tomater groft.","2.","Varm en gryde op med olivenolie og sauter løg under omrøring i ca. 5 minutter, til de er glaserede.","3.","Kom hvidløg, tomater, frisk timian, rød chili og sukker i og rør det rundt i 1-2 minutter.","4.","Kom balsamicoeddiken ved og lad det bruse af i 1 minut.","5.","Kom flåede tomater og vand i og lad det småsimre i 10 minutter uden låg.","6.","Blend tomatblandingen med en stavblender og smag til med salt.","7.","Kog spaghetti al dente i kogende vand tilsat salt.","8.","Si vandet fra med en sigte, og kom spaghetti tilbage i gryden.","9.","Vend tomatsaucen godt sammen med spaghettien og servér straks på lune tallerkener.","10.","Anret med revet parmesanost og frisk basilikum.","Klima Kærlig opskrift","Pastaret","Frokost","Hovedret","Næringsindhold:","Energiindhold for hele retten:","2701 kj / 645 kcal","Næringsindhold pr. 100g","243 kj / 58 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.9 g","Protein:\t17.5 %\t2.5 g","Kulhydrat:\t24.1 %\t3.5 g","Fedt:\t58.4 %\t3.8 g","Alkohol:\t0 %\t0.0 g","0 stemmer","Bedøm opskriften","Relaterede opskrifter","Pastasalat med grønne asparges og bønner og persillepesto med skyr","Frokost","0-30 min","Se opskrift","Spaghetti med artiskokker, mozzarella, ærter og citron","Hovedret","30-60 min","Se opskrift","Pasta med soltørrede tomater og squash","Frokost","0-30 min","Se opskrift","One pot pasta med courgette, ærter og basilikum","Hovedret","0-30 min","Se opskrift","Fuldkornspasta med Karolines hytteost med grillet peberfrugt","Frokost","0-30 min","Se opskrift","NÆSTE","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_loeg","amount":2,"unit":"små løg","text":"2 små løg"},{"raavare_id":"ing_loeg","amount":4,"unit":"fed hvidløg","text":"4 fed hvidløg"},{"raavare_id":"ing_extra_1","amount":3,"unit":"tomater","text":"3 tomater"},{"raavare_id":"ing_extra_31","amount":2,"unit":"spsk olivenolie","text":"2 spsk olivenolie"},{"raavare_id":"ing_ris","amount":2,"unit":"spsk frisk timian","text":"2 spsk frisk timian"},{"raavare_id":null,"amount":0.5,"unit":"lille rød chilipeber","text":"0.5 lille rød chilipeber"},{"raavare_id":"ing_extra_30","amount":1,"unit":"tsk sukker","text":"1 tsk sukker"},{"raavare_id":null,"amount":1,"unit":"spsk hvid balsamicoeddike","text":"1 spsk hvid balsamicoeddike"},{"raavare_id":"ing_extra_1","amount":1,"unit":"dåse flået tomat","text":"1 dåse flået tomat"},{"raavare_id":null,"amount":2,"unit":"dl vand","text":"2 dl vand"},{"raavare_id":"ing_extra_43","amount":1,"unit":"tsk havsalt","text":"1 tsk havsalt"},{"raavare_id":null,"amount":50,"unit":"g revet parmigiano reggiano","text":"50 g revet parmigiano reggiano"},{"raavare_id":"ing_ris","amount":1,"unit":"dl frisk basilikum","text":"1 dl frisk basilikum"}]'::jsonb, '[]'::jsonb);
INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_R3JpbGxldCBmbMO', 'Grillet flæskestegssandwich', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/grillet-flaskestegssandwich/4596839.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["Tilberedning","1.","Gnid flæskestegen med salt og peber, og grill den ved indirekte varme, eller steg den i ovnen i 45 min. til 1 time ved 200 °C, eller til den har en centrumtemperatur på 74 °C.","2.","Skær stegen i skiver.","3.","Snit kålen fint, og bland med revet gulerod og ærteskud.","4.","Vend salaten sammen med olivenolie og hvidvinseddike, og krydr med lidt salt og peber.","5.","Lun burgerbollerne, og smør dem med sriracha mayo.","6.","Kom 1-2 skiver flæskesteg i hver burger, og top med salat og syltede agurker.","Grill","SPISETID opskrift","Sandwich","Forår","Sommer","Svin","Næringsindhold:","Energiindhold for hele retten:","17697 kj / 4227 kcal","Næringsindhold pr. 100g","948 kj / 227 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t0.9 g","Protein:\t20.9 %\t11.7 g","Kulhydrat:\t13.7 %\t7.6 g","Fedt:\t65.4 %\t16.8 g","Alkohol:\t0 %\t0.0 g","20 stemmer","Bedøm opskriften","Relaterede opskrifter","Grillede pølser med knust agurkesalat og grov ærtehummus","Frokost","30-60 min","Se opskrift","Grillspyd med brunchpølser og grønt","Tilbehør","30-60 min","Se opskrift","Om MENY","Kontakt os","Job i MENY","Om MENY","Kundeservice","Konkurrencer & Vilkår","Gavekort","Kundeinformation","Anmodning om indsigt","Privatlivspolitik","Tilgængelighedserklæring","Cookiepolitik","Genveje","Find butik","Fordelsapp","MENY Vin","Mad ud af huset","Tilmeld nyhedsbrev","Magasinet SPISETID","Ugens avis","Ikke modtaget ugens avisen?","Ugens avis","Facebook","Youtube","Instagram",";"]'::jsonb, '[{"raavare_id":"ing_extra_14","amount":1,"unit":"kg flæskesteg","text":"1 kg flæskesteg"},{"raava