INSERT INTO recipes (id, titel, beskrivelse, billed_url, portioner, tidsforbrug_min, instruktioner, ingredienser, tags) VALUES ('meny_QnJvY2NvbGlwZXN', 'Broccolipesto med sprøde rugbrødschips', 'Importeret fra Meny', 'https://cdn-rdb.arla.com/dagrofa-dk/broccolipesto-sproede-rugbroedschips/2735059494.jpg?w=960&h=439&anchor=middlecenter&mode=crop&scale=both&ak=8567bf50&hm=73811dac', 4, 30, '["1.","Kom rå broccoli i foodprocessor og kør til det er findelt, kom ristede hasselnødder, persille ved og kør igen med foodprocessor.","2.","Tilsæt chili, knust hvidløg, vand, citronsaft, salt og oliven olie.","3.","Blend broccolipesto til ensartet konsistens.","4.","Server på rugbrødschips.","5.","Kan også bruges som dip, i pasta salat, i salat skålen eller som spread i sandwich.","Klima Kærlig opskrift","Snacks","Tilbehør","Salater","Næringsindhold:","Energiindhold for hele retten:","7248 kj / 1731 kcal","Næringsindhold pr. 100g","1206 kj / 288 kcal","Energifordeling","\tENERGIFORDELING\tNÆRINGSINDHOLD PR. 100G","Fiber:\t\t4.2 g","Protein:\t6.2 %\t4.4 g","Kulhydrat:\t12.4 %\t8.8 g","Fedt:\t81.4 %\t26.5 g","Alkohol:\t0 %\t0.0 g","1 stemmer","Bedøm opskriften","Relaterede opskrifter","Ristet rosenkål og butternut squash med bacon og granatæble","Tilbehør","30-60 min","Se opskrift","Quinoasalat med ristede rødbeder, kål og sesamdressing","Tilbehør","0-30 min","Se opskrift","Tomatsalsa med lime og koriander","Tilbehør","0-30 min","Se opskrift","Spinatsalat med blomkål og ristede pinjekerner","Tilbehør","0-30 min","Se opskrift","Frisk rødkålssalat med nødder og appelsin","Tilbehør","0-30 min","Se opskrift","Salat med avocado og semidried tomater","Tilbehør","90-120 min","Se opskrift","Spidskålstzatziki","Tilbehør","30-60 min","Se opskrift","Sommer kartoffelsalat","Tilbehør","60-90 min","Se opskrift","Bagt hokkaidosalat med, grønkål, æble og granatæble","Tilbehør","30-60 min","Se opskrift","Bagt hokkaido med yoghurt, tomater og ristede græskarkerner","Tilbehør","30-60 min","Se opsk